tasks_data = json.loads('[[101, "Oddiy if sharti va end bloki", "Foydalanuvchi balansi tekshirilib, agar 0 dan katta bo\'lsa xabar chiqaruvchi shartli blok yozing.", "balans = 45000\\nif balans > 0\\n  puts \\"Sizning balansingiz ijobiy: #{balans} so\'m\\"\\nend\\n", "Ruby-da \'if\' shartli operatori shart rost (truthy) bo\'lgan taqdirda \'end\' gacha bo\'lgan kod blokini bajaradi. Qavslar qo\'yish majburiy emas.", "Sizning balansingiz ijobiy: 45000 so\'m"], [102, "if ... else konstruksiyasi", "Foydalanuvchining yoshi 18 dan katta yoki tengligiga qarab ovoz berish huquqini aniqlang.", "yosh = 17\\nif yosh >= 18\\n  puts \\"Siz ovoz berish huquqiga egasiz.\\"\\nelse\\n  puts \\"Kechirasiz, siz hali voyaga yetmagansiz. Qolgan yillar: #{18 - yosh}\\"\\nend\\n", "\'if ... else\' shart rost bo\'lmaganda \'else\' tarmog\'idagi muqobil ko\'rsatmalarni bajarish imkonini beradi.", "Kechirasiz, siz hali voyaga yetmagansiz. Qolgan yillar: 1"], [103, "if ... elsif ... else ko\'p tarmoqli shart", "Talabaning to\'plagan foiziga qarab uning akademik bahosini (A, B, C, D, F) belgilang.", "ball = 82\\n\\nif ball >= 90\\n  baho = \\"A (A\'lo)\\"\\nelsif ball >= 80\\n  baho = \\"B (Yaxshi)\\"\\nelsif ball >= 70\\n  baho = \\"C (Qoniqarli)\\"\\nelsif ball >= 60\\n  baho = \\"D (Yetarli)\\"\\nelse\\n  baho = \\"F (Qoniqarsiz)\\"\\nend\\n\\nputs \\"Talaba natijasi: #{ball}% -> Baho: #{baho}\\"\\n", "Ruby-da ko\'p shartli tekshiruvlar uchun \'elsif\' (e\'tibor bering: \'else if\' yoki \'elif\' emas, aynan \'elsif\') kalit so\'zi qo\'llaniladi.", "Talaba natijasi: 82% -> Baho: B (Yaxshi)"], [104, "Qator oxiridagi shart (Modifier if)", "Dasturiy jurnalga (log) faqat debug rejimi yoqilgan bo\'lsa xabar yozuvchi bir qatorli if yozing.", "debug_rejim = true\\nputs \\"[DEBUG] Tizim xotirasi tekshirilmoqda...\\" if debug_rejim\\n", "Ruby sintaksisining go\'zalliklaridan biri \'Statement Modifier\' bo\'lib, harakatni shartdan oldin bitta qatorda yozishga imkon beradi (`kod if shart`). Bu kodni ixcham va ravon qiladi.", "[DEBUG] Tizim xotirasi tekshirilmoqda..."], [105, "unless operatori (inkor shart)", "Foydalanuvchi tizimda bloklanmagan bo\'lsagina ma\'lumotlarni ko\'rsating.", "bloklangan = false\\n\\nunless bloklangan\\n  puts \\"Xush kelibsiz! Shaxsiy kabinetga kirish muvaffaqiyatli.\\"\\nend\\n", "\'unless\' kalit so\'zi \'if not\' (agar shunday bo\'lmasa) degan ma\'noni bildiradi. U shart yolg\'on (false yoki nil) bo\'lganda ishlaydi. Bu \'if !shart\' yozishdan ancha toza va tabiiy o\'qiladi.", "Xush kelibsiz! Shaxsiy kabinetga kirish muvaffaqiyatli."], [106, "Qator oxiridagi unless (Modifier unless)", "To\'lov amalga oshirilmagan bo\'lsa darhol xizmatni to\'xtatuvchi bitta qatorli modifier unless yozing.", "tolangan = false\\nputs \\"Ogohlantirish: Hisobingizni to\'ldiring!\\" unless tolangan\\n", "Modifier unless bir qatorda shart yolg\'on bo\'lganda bajariladigan amallarni qisqa yozish uchun xizmat qiladi.", "Ogohlantirish: Hisobingizni to\'ldiring!"], [107, "unless ... else konstruksiyasi", "Foydalanuvchi paroli xavfsizlik talablariga javob bermasa ogohlantiring.", "parol_kuchsiz = false\\n\\nunless parol_kuchsiz\\n  puts \\"Parol juda kuchli va xavfsiz.\\"\\nelse\\n  puts \\"Iltimos, parolingizni murakkablashtiring.\\"\\nend\\n", "\'unless ... else\' ishlatish mumkin, ammo kod tushunarsiz bo\'lib qolmasligi uchun odatda \'if ... else\' afzal ko\'riladi.", "Parol juda kuchli va xavfsiz."], [108, "case ... when selektori va qiymatlarni solishtirish", "Hafta kuni raqami bo\'yicha uning nomini o\'zbek tilida chiqaruvchi case tuzilmasini yarating.", "kun_raqami = 3\\n\\nnom = case kun_raqami\\nwhen 1 then \\"Dushanba\\"\\nwhen 2 then \\"Seshanba\\"\\nwhen 3 then \\"Chorshanba\\"\\nwhen 4 then \\"Payshanba\\"\\nwhen 5 then \\"Juma\\"\\nwhen 6 then \\"Shanba\\"\\nwhen 7 then \\"Yakshanba\\"\\nelse \\"Noto\'g\'ri kun raqami\\"\\nend\\n\\nputs \\"3-kun: #{nom}\\"\\n", "Ruby-dagi \'case ... when\' boshqa tillardagi switch-case ga o\'xshaydi, lekin unda \'break\' yozish talab etilmaydi. Mos kelgan birinchi tarmoq bajariladi va blokdan chiqiladi.", "3-kun: Chorshanba"], [109, "case ichida bir nechta qiymat (vergul bilan)", "Oy raqamiga qarab faslni (qish, bahor, yoz, kuz) aniqlang.", "oy = 7\\n\\nfasl = case oy\\nwhen 12, 1, 2\\n  \\"Qish\\"\\nwhen 3, 4, 5\\n  \\"Bahor\\"\\nwhen 6, 7, 8\\n  \\"Yoz\\"\\nwhen 9, 10, 11\\n  \\"Kuz\\"\\nelse\\n  \\"Noma\'lum oy\\"\\nend\\n\\nputs \\"#{oy}-oy: #{fasl} fasli\\"\\n", "\'when\' dan keyin bir nechta qiymatlarni vergul bilan yozish mumkin. Agar o\'zgaruvchi ularning istalgan biriga teng bo\'lsa, tarmoq ishga tushadi.", "7-oy: Yoz fasli"], [110, "case ichida Range (oraliqlar) ishlatish", "Mijozning yoshiga qarab toifani (chaqaloq, bola, o\'smir, katta, keksalar) Range orqali aniqlang.", "yosh = 24\\n\\ntoifa = case yosh\\nwhen 0..2   then \\"Chaqaloq\\"\\nwhen 3..12  then \\"Bola\\"\\nwhen 13..19 then \\"O\'smir\\"\\nwhen 20..59 then \\"Katta yoshli fuqaro\\"\\nelse \\"Keksa nuroniy\\"\\nend\\n\\nputs \\"Yosh: #{yosh} -> Toifa: #{toifa}\\"\\n", "Ruby-da \'case\' operatori sahna ortida \'===\' (case equality) operatoridan foydalanadi. Range uchun `(20..59) === yosh` son oraliqda borligini tekshiradi.", "Yosh: 24 -> Toifa: Katta yoshli fuqaro"], [111, "case ichida Regex (muntazam ifodalar)", "Kiritilgan satrning turini (raqam, telefon raqam, oddiy matn) Regex bilan tekshiring.", "kiruvchi = \\"+998901234567\\"\\n\\nturi = case kiruvchi\\nwhen /\\\\A\\\\+998\\\\d{9}\\\\z/\\n  \\"O\'zbekiston telefon raqami\\"\\nwhen /\\\\A\\\\d+\\\\z/\\n  \\"Faqat raqamlardan iborat butun son\\"\\nelse\\n  \\"Oddiy matn\\"\\nend\\n\\nputs \\"Kiruvchi ma\'lumot: #{kiruvchi} -> Turi: #{turi}\\"\\n", "Regexp obyekti uchun `regex === satr` amali satrning andozaga mosligini tekshiradi. Bu \'case\' ichida kuchli parserlar yaratish imkonini beradi.", "Kiruvchi ma\'lumot: +998901234567 -> Turi: O\'zbekiston telefon raqami"], [112, "case ichida sinflar (Class) bo\'yicha tekshirish", "O\'zgaruvchining toifasiga qarab mos qayta ishlashni tanlang.", "qiymat = 3.1415\\n\\nxabar = case qiymat\\nwhen Integer\\n  \\"Butun son kiritildi: #{qiymat}\\"\\nwhen Float\\n  \\"Haqiqiy son kiritildi: #{qiymat.round(2)}\\"\\nwhen String\\n  \\"Matn kiritildi: #{qiymat.upcase}\\"\\nelse\\n  \\"Boshqa toifa: #{qiymat.class}\\"\\nend\\n\\nputs xabar\\n", "Sinf obyekti uchun `Class === obyekt` amali `obyekt.is_a?(Class)` kabi ishlaydi. Shu tufayli case yordamida polimorfik tiplarni tekshirish mumkin.", "Haqiqiy son kiritildi: 3.14"], [113, "Shartsiz case (Condition-less case)", "O\'zgaruvchisiz, har bir when tarmog\'ida alohida mantiqiy ifoda tekshiriladigan case tuzing.", "harorat = 28\\nnamlik = 65\\n\\ntavsiya = case\\nwhen harorat > 35 && namlik > 70\\n  \\"Juda issiq va dim havo, konditsioner yoqing.\\"\\nwhen harorat > 25 && namlik <= 70\\n  \\"Ajoyib iliq ob-havo, sayr qilish mumkin.\\"\\nwhen harorat < 10\\n  \\"Sovuq havo, issiq kiyining.\\"\\nelse\\n  \\"O\'rtacha me\'yordagi havo.\\"\\nend\\n\\nputs \\"Tavsiya: #{tavsiya}\\"\\n", "Agar \'case\' dan keyin hech qanday o\'zgaruvchi ko\'rsatilmasa, u \'if ... elsif\' zanjirining eng toza va go\'zal muqobiliga aylanadi.", "Tavsiya: Ajoyib iliq ob-havo, sayr qilish mumkin."], [114, "case ifoda sifatida (Expression return)", "Case blokidan to\'g\'ridan-to\'g\'ri qiymat qaytarishni o\'zlashtiring.", "til = \\"uz\\"\\nsalom = case til\\n        when \\"uz\\" then \\"Salom dunyo!\\"\\n        when \\"en\\" then \\"Hello world!\\"\\n        when \\"ru\\" then \\"Привет мир!\\"\\n        end\\n\\nputs salom\\n", "Ruby-da deyarli barcha konstruksiyalar (if, unless, case) ibora (expression) hisoblanadi va qiymat qaytaradi. Ular to\'g\'ridan-to\'g\'ri o\'zgaruvchiga biriktirilishi mumkin.", "Salom dunyo!"], [115, "Ruby 3.0 Pattern Matching: case ... in asoslari", "Ruby 3 dagi zamonaviy pattern matching orqali ma\'lumot tuzilmasini solishtiring.", "javob = { status: :ok, kod: 200 }\\n\\ncase javob\\nin { status: :ok, kod: 200 }\\n  puts \\"Server muvaffaqiyatli javob berdi (200 OK)\\"\\nin { status: :error, kod: 404 }\\n  puts \\"Sahifa topilmadi (404 Not Found)\\"\\nelse\\n  puts \\"Noma\'lum server javobi\\"\\nend\\n", "Ruby 3.0 da kiritilgan \'case ... in\' sintaksisi Pattern Matching imkoniyatini taqdim etadi. U obyektning nafaqat qiymatini, balki shakli va ichki strukturasini chuqur tekshiradi.", "Server muvaffaqiyatli javob berdi (200 OK)"], [116, "Pattern Matching: Massivlar dekonstruksiyasi", "Buyruq va parametrlardan iborat massivni pattern matching orqali o\'zgaruvchilarga ajrating.", "buyruq = [\\"user\\", \\"create\\", \\"Alisher\\"]\\n\\ncase buyruq\\nin [\\"user\\", \\"create\\", ism]\\n  puts \\"Yangi foydalanuvchi yaratilmoqda: #{ism}\\"\\nin [\\"user\\", \\"delete\\", id]\\n  puts \\"Foydalanuvchi o\'chirilmoqda: ID = #{id}\\"\\nelse\\n  puts \\"Noma\'lum buyruq\\"\\nend\\n", "Massiv dekonstruksiyasida `in [a, b, c]` andozasi mos kelsa, andozadagi o\'zgaruvchilar (ism, id) avtomatik qiymatlarni o\'ziga oladi (binding).", "Yangi foydalanuvchi yaratilmoqda: Alisher"], [117, "Pattern Matching: Hash dekonstruksiyasi", "API dan kelgan JSON ma\'lumotining kalitlarini va qiymatlarini pattern matching bilan ushlang.", "foydalanuvchi = { id: 101, rol: \\"admin\\", ism: \\"Rustam\\" }\\n\\ncase foydalanuvchi\\nin { id:, rol: \\"admin\\", ism: }\\n  puts \\"Administrator tizimga kirdi: #{ism} (ID: #{id})\\"\\nin { rol: \\"mehmon\\" }\\n  puts \\"Mehmon tashrif buyurdi.\\"\\nend\\n", "Hash dekonstruksiyasida `{ id:, ism: }` sintaksisi o\'sha nomli kalitlarning qiymatlarini avtomatik bir xil nomli lokal o\'zgaruvchilarga biriktiradi.", "Administrator tizimga kirdi: Rustam (ID: 101)"], [118, "Pattern Matching shartli qo\'shimchasi (Guard if/unless)", "Pattern matching mosligiga qo\'shimcha mantiqiy shart qo\'shing.", "mahsulot = { nom: \\"Smartfon\\", narx: 450 }\\n\\ncase mahsulot\\nin { nom:, narx: } if narx > 500\\n  puts \\"Qimmatbaho mahsulot: #{nom} ($#{narx})\\"\\nin { nom:, narx: }\\n  puts \\"Hamyonbop mahsulot: #{nom} ($#{narx})\\"\\nend\\n", "Pattern matching tarmog\'i oxiriga `if` yoki `unless` sharti (Guard clause) qo\'shilishi mumkin. Andoza mos kelsa ham, faqat guard sharti rost bo\'lsagina ushbu tarmoq tanlanadi.", "Hamyonbop mahsulot: Smartfon ($450)"], [119, "while sikli: shart rost bo\'lguncha takrorlash", "Hisoblagichni 1 dan 5 gacha oshirib ekranga chiqaring.", "i = 1\\nwhile i <= 5\\n  puts \\"Qadam: #{i}\\"\\n  i += 1\\nend\\n", "\'while shart\' berilgan shart rost bo\'lib turguncha kod blokini qayta-qayta bajaradi.", "Qadam: 1\\nQadam: 2\\nQadam: 3\\nQadam: 4\\nQadam: 5"], [120, "Modifier while (qator oxiridagi while)", "Massivdan elementlarni bittalab sug\'urib chiqaruvchi bir qatorli modifier while yozing.", "navbat = [\\"Mijoz 1\\", \\"Mijoz 2\\", \\"Mijoz 3\\"]\\nputs \\"Xizmat ko\'rsatildi: #{navbat.shift}\\" while !navbat.empty?\\n", "Modifier while bitta qatorda siklni qisqa yozish imkonini beradi (`harakat while shart`).", "Xizmat ko\'rsatildi: Mijoz 1\\nXizmat ko\'rsatildi: Mijoz 2\\nXizmat ko\'rsatildi: Mijoz 3"], [121, "until sikli: shart yolg\'on bo\'lguncha takrorlash", "Suv sathi 100 litrga yetguncha bakni to\'ldiruvchi until siklini tuzing.", "suv = 20\\nuntil suv >= 100\\n  suv += 30\\n  puts \\"Joriy suv hajmi: #{suv} litr\\"\\nend\\n", "\'until shart\' \'while !shart\' ning muqobili bo\'lib, ko\'rsatilgan shart to\'g\'ri bo\'lgunga qadar bajariladi.", "Joriy suv hajmi: 50 litr\\nJoriy suv hajmi: 80 litr\\nJoriy suv hajmi: 110 litr"], [122, "Modifier until", "Son 1 dan kichik bo\'lguncha uni ikkiga bo\'lib boruvchi bir qatorli until tuzing.", "son = 16\\nson /= 2 until son <= 2\\nputs \\"Yakuniy son: #{son}\\"\\n", "Modifier until qator oxirida shart bajarilguncha chap tarafdagi amaliyotni takrorlaydi.", "Yakuniy son: 2"], [123, "Cheksiz sikl: loop do ... end", "Kernel#loop metodi orqali xavfsiz cheksiz sikl yarating va unga chiqish shartini qo\'ying.", "soni = 0\\nloop do\\n  soni += 1\\n  puts \\"Sikl takrori: #{soni}\\"\\n  break if soni >= 3\\nend\\n", "\'loop\' Ruby-dagi eng sof sikl mexanizmi bo\'lib, shartsiz cheksiz aylanadi. Undan chiqish uchun \'break\' buyrug\'i ishlatiladi.", "Sikl takrori: 1\\nSikl takrori: 2\\nSikl takrori: 3"], [124, "Sikldan muddatidan oldin chiqish: break", "Raqamlar ro\'yxatidan manfiy son uchraganda qidiruvni darhol to\'xtating.", "sonlar = [12, 45, 67, -3, 89, 90]\\n\\nsonlar.each do |s|\\n  if s < 0\\n    puts \\"Manfiy son topildi: #{s}. Qidiruv to\'xtatildi!\\"\\n    break\\n  end\\n  puts \\"Qayta ishlandi: #{s}\\"\\nend\\n", "\'break\' sikl bajarilishini darhol to\'xtatadi va sikldan keyingi qatorga o\'tadi.", "Qayta ishlandi: 12\\nQayta ishlandi: 45\\nQayta ishlandi: 67\\nManfiy son topildi: -3. Qidiruv to\'xtatildi!"], [125, "Keyingi iteratsiyaga o\'tish: next", "1 dan 10 gacha bo\'lgan sonlar orasidan toq sonlarni tashlab o\'tib, faqat juftlarini chiqaring.", "(1..6).each do |s|\\n  next if s.odd?\\n  puts \\"Juft son: #{s}\\"\\nend\\n", "\'next\' operatori (boshqa tillardagi \'continue\') joriy iteratsiyaning qolgan qismini bajarmasdan, darhol keyingi iteratsiyaga o\'tadi.", "Juft son: 2\\nJuft son: 4\\nJuft son: 6"], [126, "Iteratsiyani boshidan qaytarish: redo", "Tasodifiy shart bo\'yicha joriy qadamni hisoblagichni oshirmasdan qayta bajaring.", "urinish = 0\\nqayta_bajarildi = false\\n\\nwhile urinish < 1\\n  urinish += 1\\n  puts \\"Urinish: #{urinish}\\"\\n  if !qayta_bajarildi\\n    qayta_bajarildi = true\\n    puts \\"redo chaqirilmoqda...\\"\\n    redo\\n  end\\nend\\n", "\'redo\' sikl shartini tekshirmasdan va yangi elementga o\'tmasdan, aynan joriy iteratsiyani boshidan qayta ishga tushiradi. Tarmoq xatolarini qayta urinishda (retry) juda qo\'l keladi.", "Urinish: 1\\nredo chaqirilmoqda...\\nUrinish: 2"], [127, "break bilan sikldan qiymat qaytarish", "Sikl yakunida \'break\' orqali topilgan natijani to\'g\'ridan-to\'g\'ri o\'zgaruvchiga oling.", "topilgan = (1..100).each do |n|\\n  break n if n % 7 == 0 && n % 5 == 0\\nend\\n\\nputs \\"7 va 5 ga bo\'linadigan birinchi musbat son: #{topilgan}\\"\\n", "Ruby-da \'break qiymat\' ifodasi siklni to\'xtatish bilan birga, butun sikl blokining qaytaradigan natijasi sifatida berilgan qiymatni taqdim etadi.", "7 va 5 ga bo\'linadigan birinchi musbat son: 35"], [128, "times iteratori", "Bajarilishi kerak bo\'lgan vazifani aniq 4 marta takrorlang.", "4.times do\\n  puts \\"Salom Khorazmiy AI!\\"\\nend\\n", "Integer sinfining \'times\' metodi eng qulay sikllardan biri bo\'lib, son miqdoricha marta berilgan kod blokini ishga tushiradi.", "Salom Khorazmiy AI!\\nSalom Khorazmiy AI!\\nSalom Khorazmiy AI!\\nSalom Khorazmiy AI!"], [129, "times iteratori bilan indeks parametrini olish", "0 dan boshlanuvchi indeks bilan qadamlarni chiqaring.", "3.times do |indeks|\\n  puts \\"Iteratsiya indeksi: #{indeks}\\"\\nend\\n", "\'times\' metodi blok parametriga 0 dan boshlab joriy takrorlanish tartib raqamini uzatadi.", "Iteratsiya indeksi: 0\\nIteratsiya indeksi: 1\\nIteratsiya indeksi: 2"], [130, "upto iteratori: pastdan yuqoriga qarab sanash", "10 dan 14 gacha bo\'lgan sonlarni upto orqali chiqaring.", "10.upto(13) do |son|\\n  puts \\"Son: #{son}\\"\\nend\\n", "\'son.upto(limit)\' ko\'rsatilgan limitgacha 1 tadan qo\'shib blokni chaqiradi.", "Son: 10\\nSon: 11\\nSon: 12\\nSon: 13"], [131, "downto iteratori: ortga sanash (Countdown)", "Raketa uchirilishi oldidan 3 dan 1 gacha ortga sanang.", "3.downto(1) do |son|\\n  puts \\"#{son}...\\"\\nend\\nputs \\"Start! Raketa uchirildi!\\"\\n", "\'son.downto(limit)\' boshlang\'ich sondan limitgacha kamayib boruvchi siklni bajaradi.", "3...\\n2...\\n1...\\nStart! Raketa uchirildi!"], [132, "step iteratori bilan sakrash", "0 dan 10 gacha juft sonlarni 2 qadam bilan chop eting.", "0.step(6, 2) do |son|\\n  puts \\"Juft qadam: #{son}\\"\\nend\\n", "\'son.step(limit, qadam)\' berilgan qadam bo\'yicha sakrab hisoblaydi.", "Juft qadam: 0\\nJuft qadam: 2\\nJuft qadam: 4\\nJuft qadam: 6"], [133, "for ... in sikli va uning ko\'rinish sohasi (Scope)", "for sikli va each metodi o\'rtasidagi o\'zgaruvchi ko\'rinish sohasi (scope) farqini ko\'rsating.", "for element in [1, 2, 3]\\n  yashirin = element * 10\\nend\\n# for siklida e\'lon qilingan o\'zgaruvchilar tashqarida ham yashaydi\\nputs \\"for dan keyin yashirin o\'zgaruvchi: #{yashirin}\\"\\n", "Ruby-da \'for x in to\'plam\' sintaksisi yangi ko\'rinish sohasi (scope) yaratmaydi, undagi o\'zgaruvchilar tashqarida ham saqlanib qoladi. Shu sababli Ruby jamoasi har doim \'each\' metodidan foydalanishni tavsiya qiladi.", "for dan keyin yashirin o\'zgaruvchi: 30"], [134, "Ichma-ich (Nested) sikllar va koordinatalar katagi", "2x3 o\'lchamli katak koordinatalarini ichma-ich sikl bilan hosil qiling.", "(1..2).each do |qator|\\n  (1..3).each do |ustun|\\n    print \\"[#{qator},#{ustun}] \\"\\n  end\\n  puts \\"\\"\\nend\\n", "Ichma-ich sikllar matritsalar, panellar va ko\'p o\'lchovli koordinatalarni aylanib chiqishda qo\'llaniladi.", "[1,1] [1,2] [1,3] \\n[2,1] [2,2] [2,3]"], [135, "Ichma-ich sikllardan break orqali chiqish chegarasi", "Ichki sikldagi break faqat ichki siklni to\'xtatishini ko\'rsating.", "(1..2).each do |tashqi|\\n  puts \\"Tashqi: #{tashqi}\\"\\n  (1..5).each do |ichki|\\n    if ichki == 2\\n      puts \\"  Ichki to\'xtatildi (break)\\"\\n      break\\n    end\\n    puts \\"  Ichki: #{ichki}\\"\\n  end\\nend\\n", "Oddiy \'break\' faqat o\'zi joylashgan eng yaqin ichki siklni to\'xtatadi, tashqi sikl o\'z ishini davom ettiradi.", "Tashqi: 1\\n  Ichki: 1\\n  Ichki to\'xtatildi (break)\\nTashqi: 2\\n  Ichki: 1\\n  Ichki to\'xtatildi (break)"], [136, "catch va throw orqali chuqur qatlamlardan bir zumda chiqish", "Ko\'p qavatli ichma-ich sikllardan bitta throw buyrug\'i bilan eng tashqariga sakrab chiqing.", "natija = catch(:topildi) do\\n  (1..10).each do |x|\\n    (1..10).each do |y|\\n      if x * y == 42\\n        throw(:topildi, \\"Mos juftlik topildi: x=#{x}, y=#{y}\\")\\n      end\\n    end\\n  end\\n  \\"Hech narsa topilmadi\\"\\nend\\n\\nputs natija\\n", "Ruby-da \'catch\' va \'throw\' istisnolar (Exceptions) emas, balki chuqur o\'ralgan kod bloklaridan zudlik bilan chiqish va kerakli qiymatni qaytarish uchun mo\'ljallangan tejamkor boshqaruv oqimi vositasidir.", "Mos juftlik topildi: x=6, y=7"], [137, "Falsy qiymatlar: faqat nil va false", "Ruby-da faqat nil va false shartda yolg\'on hisoblanishini ko\'rsating.", "def tekshir(qiymat)\\n  if qiymat\\n    \\"#{qiymat.inspect} -> ROST (Truthy)\\"\\n  else\\n    \\"#{qiymat.inspect} -> YOLG\'ON (Falsy)\\"\\n  end\\nend\\n\\nputs tekshir(false)\\nputs tekshir(nil)\\nputs tekshir(0)\\nputs tekshir(\\"\\")\\nputs tekshir([])\\n", "C, Python yoki JavaScript-dan farqli o\'laroq, Ruby-da 0 soni, bo\'sh satr \\"\\" va bo\'sh massiv [] ham to\'liq ROST (Truthy) hisoblanadi. Faqat ikkita narsa: \'false\' va \'nil\' yolg\'on hisoblanadi.", "false -> YOLG\'ON (Falsy)\\nnil -> YOLG\'ON (Falsy)\\n0 -> ROST (Truthy)\\n\\"\\" -> ROST (Truthy)\\n[] -> ROST (Truthy)"], [138, "Mantiqiy qisqa tutashuv (Short-circuit evaluation)", "Birinchi shart yetarli bo\'lganda ikkinchi funksiya chaqirilmasligini isbotlang.", "def xavfli_metod\\n  puts \\"XAVFLI METOD CHAQIRILDI!\\"\\n  true\\nend\\n\\n# Chap taraf false bo\'lgani uchun && o\'ng tarafni umuman bajarmaydi\\nfalse && xavfli_metod\\nputs \\"&& amali yakunlandi (metod chaqirilmadi).\\"\\n\\n# Chap taraf true bo\'lgani uchun || o\'ng tarafni umuman bajarmaydi\\ntrue || xavfli_metod\\nputs \\"|| amali yakunlandi (metod chaqirilmadi).\\"\\n", "Short-circuit evaluation mantiqiy ifodalarda ortiqcha hisob-kitoblar va xatolarning (masalan nil.metod) oldini oladi.", "&& amali yakunlandi (metod chaqirilmadi).\\n|| amali yakunlandi (metod chaqirilmadi)."], [139, "Shartli operatorlarda tasodifiy biriktirish xatosi", "Solishtirish (==) o\'rniga biriktirish (=) yozilganda Ruby qanday ogohlantirish berishini ko\'ring.", "x = 10\\n# if x = 20 qilsak, biriktirish yuz beradi va doim true bo\'ladi\\nif x == 20\\n  puts \\"Teng\\"\\nelse\\n  puts \\"Teng emas: x ning haqiqiy qiymati #{x}\\"\\nend\\n", "Ruby kompilyatori `if x = 20` kabi kodlarda \'warning: found = in conditional, should be ==\' ogohlantirishini beradi.", "Teng emas: x ning haqiqiy qiymati 10"], [140, "Fibonachchi sonlarini while sikli bilan hisoblash", "Dastlabki 8 ta Fibonachchi sonlarini hisoblang.", "n = 8\\nfibo = [0, 1]\\nwhile fibo.length < n\\n  fibo << fibo[-1] + fibo[-2]\\nend\\n\\nputs \\"Dastlabki #{n} ta Fibonachchi soni: #{fibo.inspect}\\"\\n", "Fibonachchi qatorida har bir yangi son o\'zidan oldingi ikkita sonning yig\'indisiga teng.", "Dastlabki 8 ta Fibonachchi soni: [0, 1, 1, 2, 3, 5, 8, 13]"], [141, "Tub sonlarni tekshirish algoritmi", "Berilgan son tub (faqat 1 ga va o\'ziga bo\'linadigan) ekanligini sikl orqali aniqlang.", "def tub_sonmi?(son)\\n  return false if son <= 1\\n  (2..Math.sqrt(son)).each do |i|\\n    return false if son % i == 0\\n  end\\n  true\\nend\\n\\nputs \\"17 tub sonmi? #{tub_sonmi?(17)}\\"\\nputs \\"24 tub sonmi? #{tub_sonmi?(24)}\\"\\n", "Sonning kvadrat ildizigacha bo\'lgan sonlarga bo\'lib ko\'rish eng tejamkor tublik tekshiruvlaridan biridir.", "17 tub sonmi? true\\n24 tub sonmi? false"], [142, "Raqamlar yig\'indisini hisoblovchi sikl", "Berilgan butun sonning raqamlari yig\'indisini bo\'lish va qoldiq olish orqali hisoblang.", "son = 4857\\nyigindi = 0\\nvaqtinchalik = son\\n\\nwhile vaqtinchalik > 0\\n  raqam = vaqtinchalik % 10\\n  yigindi += raqam\\n  vaqtinchalik /= 10\\nend\\n\\nputs \\"#{son} sonining raqamlari yig\'indisi: #{yigindi}\\"\\n", "Har bir qadamda 10 ga bo\'lib qoldiq olish oxirgi raqamni ajratadi.", "4857 sonining raqamlari yig\'indisi: 24"], [143, "Sonning barcha bo\'luvchilarini topish", "Berilgan sonning barcha qoldiqsiz bo\'luvchilarini massivga yig\'ing.", "son = 36\\nboluvchilar = []\\n\\n1.upto(son) do |i|\\n  boluvchilar << i if son % i == 0\\nend\\n\\nputs \\"#{son} ning bo\'luvchilari: #{boluvchilar.inspect}\\"\\n", "1 dan songacha bo\'lgan sonlar orasidan qoldiqsiz bo\'linuvchilar saralanadi.", "36 ning bo\'luvchilari: [1, 2, 3, 4, 6, 9, 12, 18, 36]"], [144, "Evklid algoritmi: EKUB (Eng Katta Umumiy Bo\'luvchi)", "Ikkita sonning EKUBini until sikli orqali toping.", "a = 48\\nb = 18\\n\\nuntil b == 0\\n  a, b = b, a % b\\nend\\n\\nputs \\"EKUB(48, 18) = #{a}\\"\\n", "Evklid algoritmi bo\'yicha `(a, b) = (b, a % b)` amali `b == 0` bo\'lgunga qadar takrorlanadi.", "EKUB(48, 18) = 6"], [145, "Sonni teskari tartibda yozish (Reverse Integer)", "12345 sonini arifmetik sikl orqali 54321 ga aylantiring.", "asl_son = 12345\\nteskari = 0\\nn = asl_son\\n\\nwhile n > 0\\n  teskari = (teskari * 10) + (n % 10)\\n  n /= 10\\nend\\n\\nputs \\"Asl son: #{asl_son} -> Teskari: #{teskari}\\"\\n", "Raqamlarni arifmetik siljitish orqali yangi teskari son shakllantiriladi.", "Asl son: 12345 -> Teskari: 54321"], [146, "Sikllarda bir nechta shartlar: and/or kombinatsiyasi", "Foydalanuvchi urinishlari soni va muvaffaqiyat holatini bir vaqtda boshqaring.", "urinishlar = 0\\nmuvaffaqiyat = false\\n\\nwhile urinishlar < 3 && !muvaffaqiyat\\n  urinishlar += 1\\n  puts \\"Urinish raqami: #{urinishlar}\\"\\n  muvaffaqiyat = true if urinishlar == 2\\nend\\n\\nputs \\"Natija: #{muvaffaqiyat ? \'Muvaffaqiyatli\' : \'Muvaffaqiyatsiz\'}\\"\\n", "Bir nechta mantiqiy shartlar bilan sikl oqimi boshqariladi.", "Urinish raqami: 1\\nUrinish raqami: 2\\nNatija: Muvaffaqiyatli"], [147, "Shartli operatorlarda ternary zanjiri", "Ballga qarab natijani bitta qatorda ternary zanjiri bilan belgilang.", "ball = 75\\nholat = ball >= 86 ? \\"A\'lo\\" : (ball >= 71 ? \\"Yaxshi\\" : \\"Qoniqarli\\")\\n\\nputs \\"Natija: #{holat}\\"\\n", "Ternary operatorlarini ichma-ich zanjir qilish mumkin, biroq murakkab holatlarda case ishlatish tavsiya etiladi.", "Natija: Yaxshi"], [148, "Kvadrat ildiz qidirish (Nyuton-Rafson usuli)", "Matematik yaqinlashish usuli bilan sonning ildizini hisoblang.", "son = 25.0\\ntaxmin = son / 2.0\\naniqlik = 0.0001\\n\\nwhile (taxmin * taxmin - son).abs > aniqlik\\n  taxmin = (taxmin + son / taxmin) / 2.0\\nend\\n\\nputs \\"25 ning taxminiy kvadrat ildizi: #{taxmin.round(4)}\\"\\n", "Nyuton algoritmi har bir qadamda qiymatni haqiqiy ildizga yaqinlashtirib boradi.", "25 ning taxminiy kvadrat ildizi: 5.0"], [149, "Shartlarda oraliq tekshiruvi: between? metodi", "Harorat normal chegarada ekanligini between? metodi orqali aniqlang.", "harorat = 36.6\\n\\nif harorat.between?(36.0, 37.0)\\n  puts \\"Tana harorati me\'yorda: #{harorat}C\\"\\nelse\\n  puts \\"Ogohlantirish: Shifokorga murojaat qiling!\\"\\nend\\n", "Comparable modulidagi \'between?(min, max)\' metodi son oraliqda borligini tekshiradi.", "Tana harorati me\'yorda: 36.6C"], [150, "Amaliy loyiha: Bankomat (ATM) kassa mashinasi va kupyuralar taqsimoti", "Mijoz so\'ragan naqd pul summasini 100 000, 50 000, 20 000 va 10 000 so\'mlik kupyuralarga optimal taqsimlovchi dastur yozing.", "yechib_olinadigan_summa = 380_000\\nkupyuralar = [100_000, 50_000, 20_000, 10_000]\\n\\nputs \\"So\'ralgan summa: #{yechib_olinadigan_summa} so\'m\\"\\nputs \\"Beriladigan kupyuralar:\\"\\n\\nqoldiq = yechib_olinadigan_summa\\nkupyuralar.each do |kupyura|\\n  if qoldiq >= kupyura\\n    soni, qoldiq = qoldiq.divmod(kupyura)\\n    puts \\"  - #{kupyura} so\'mlik: #{soni} dona\\"\\n  end\\nend\\n\\nif qoldiq == 0\\n  puts \\"Tranzaksiya muvaffaqiyatli yakunlandi.\\"\\nelse\\n  puts \\"Qoldiq berib bo\'lmadi: #{qoldiq} so\'m\\"\\nend\\n", "Ushbu amaliy loyihada Ruby 03 mavzusining asosiy shart va sikl mexanizmlari (each, if, divmod va hisoblagichlar) bitta real bankomat tizimi misolida birlashtirildi.", "So\'ralgan summa: 380000 so\'m\\nBeriladigan kupyuralar:\\n  - 100000 so\'mlik: 3 dona\\n  - 50000 so\'mlik: 1 dona\\n  - 20000 so\'mlik: 1 dona\\n  - 10000 so\'mlik: 1 dona\\nTranzaksiya muvaffaqiyatli yakunlandi."]]')

